import{_ as s,o as t,c as a,a2 as r}from"./chunks/framework.ChIlRNAd.js";const h=JSON.parse('{"title":"Pièces jointes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/attachments.md","filePath":"fr/guide/attachments.md"}'),o={name:"fr/guide/attachments.md"};function i(n,e,l,c,u,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="pieces-jointes" tabindex="-1">Pièces jointes <a class="header-anchor" href="#pieces-jointes" aria-label="Permalink to &quot;Pièces jointes&quot;">​</a></h1><p>La page <strong>Pièces jointes</strong> (<code>/attachments</code>) liste toutes les pièces jointes du compte actif, des plus lourdes aux plus légères. Elle n&#39;a pas d&#39;entrée dans la barre latérale : ouvrez-la depuis la palette de commandes (<code>⌘K</code> / <code>Ctrl+K</code>, groupe <strong>Autres pages</strong>).</p><p>Pour un tri rapide des gros mails avec actions de masse, l&#39;onglet <strong>Gros mails &amp; pièces jointes</strong> de <a href="./cleanup.html#gros-mails-pieces-jointes">Nettoyage</a> suffit généralement.</p><hr><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Deux boutons choisissent la source :</p><ul><li><strong>Archives</strong> (par défaut) : pièces jointes des mails sauvegardés sur le NAS. Une recherche <strong>par nom, sujet, expéditeur ou contenu</strong> est disponible : le texte des PDF et des documents Word (.docx) est cherché aussi (mêmes règles que la recherche des <a href="./archives.html">Archives</a> : sans accents, <code>&quot;phrase exacte&quot;</code>, <code>-exclure</code>, <code>OR</code>), et l&#39;extrait trouvé s&#39;affiche sous le nom du fichier.</li><li><strong>Live</strong> : pièces jointes de plus de 100 Ko encore dans Gmail.</li></ul><p>La source, la recherche et la page sont gardées dans l&#39;adresse. <strong>Recharger</strong> relance le chargement.</p><hr><h2 id="indicateurs" tabindex="-1">Indicateurs <a class="header-anchor" href="#indicateurs" aria-label="Permalink to &quot;Indicateurs&quot;">​</a></h2><ul><li><strong>Pièces jointes</strong> : nombre de fichiers ;</li><li><strong>Taille totale</strong> ;</li><li><strong>Source</strong> : « Archives locales » ou « Gmail (&gt;100 Ko) » ;</li><li><strong>Espace économisé</strong> : gain de la déduplication des pièces jointes archivées (« N fichier(s) dupliqué(s), X économisés »). Un fichier identique (même contenu) n&#39;est écrit qu&#39;une fois par compte, que le mail vienne d&#39;une sauvegarde Gmail, d&#39;un compte IMAP ou d&#39;un import mbox / .eml. Si une partie des fichiers archivés avant cette déduplication n&#39;a pas encore été analysée, le bouton <strong>Analyser</strong> lance ce calcul et fusionne les doublons.</li></ul><hr><h2 id="liste" tabindex="-1">Liste <a class="header-anchor" href="#liste" aria-label="Permalink to &quot;Liste&quot;">​</a></h2><p>Colonnes : <strong>Fichier</strong>, <strong>Mail</strong>, <strong>Taille</strong>, <strong>Date</strong>, <strong>Type</strong>, <strong>Actions</strong>. La liste est paginée.</p><ul><li><strong>Télécharger</strong> : enregistre le fichier.</li><li><strong>Voir</strong> : ouvre le fichier dans le navigateur, seulement pour les images (PNG, JPEG, GIF, WebP) et les PDF.</li></ul>',15)])])}const p=s(o,[["render",i]]);export{h as __pageData,p as default};
